'use strict';

// MODULES //

var addon = require( './../src/addon.node' );


// MAIN //

/**
* Returns the index of the first element in a sorted single-precision floating-point strided array which is greater than or equal to a specified search element.
*
* ## Notes
*
* -   If unable to find an element which is greater than or equal to the search element, the function returns `-1`.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {number} searchElement - search element
* @param {Float32Array} x - sorted input array
* @param {integer} strideX - stride length
* @returns {integer} index
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
*
* var x = new Float32Array( [ 1.0, 2.0, 2.0, 3.0 ] );
*
* var idx = sindexOfGreaterThanEqualSorted( x.length, 2.0, x, 1 );
* // returns 1
*/
function sindexOfGreaterThanEqualSorted( N, searchElement, x, strideX ) {
	return addon( N, searchElement, x, strideX );
}


// EXPORTS //

module.exports = sindexOfGreaterThanEqualSorted;
